// Draw stack of vinyl records
const recordWidth = 250;
const recordHeight = 150;
const margin = 20;
const stackHeight = 300;

// Draw base record
ctx.fillStyle = '#2d1b69';
ctx.fillRect(margin, margin + stackHeight - recordHeight, recordWidth, recordHeight);

// Draw inner groove
ctx.strokeStyle = '#5d4037';
ctx.lineWidth = 2;
ctx.beginPath();
ctx.arc(margin + recordWidth/2, margin + stackHeight - recordHeight/2, 100, 0, Math.PI * 2);
ctx.stroke();

// Draw outer groove
ctx.beginPath();
ctx.arc(margin + recordWidth/2, margin + stackHeight - recordHeight/2, 120, 0, Math.PI * 2);
ctx.stroke();

// Draw label
ctx.fillStyle = '#f44336';
ctx.fillRect(margin + 10, margin + stackHeight - 80, 220, 60);

// Draw label details
ctx.fillStyle = '#ffffff';
ctx.font = 'bold 16px Arial';
ctx.fillText('VINYL', margin + 30, margin + stackHeight - 50);
ctx.fillText('RECORD', margin + 30, margin + stackHeight - 30);

// Draw center hole
ctx.fillStyle = '#e0e0e0';
ctx.beginPath();
ctx.arc(margin + recordWidth/2, margin + stackHeight - recordHeight/2, 20, 0, Math.PI * 2);
ctx.fill();

// Draw some grooves for depth
ctx.strokeStyle = '#3e2723';
ctx.lineWidth = 1;
for (let i = 0; i < 10; i++) {
    const angle = (i / 10) * Math.PI * 2;
